package com.zineb.chat.client.view;
import javafx.geometry.Insets; import javafx.scene.Parent; import javafx.scene.control.*; import javafx.scene.layout.*; import javafx.scene.paint.Color; import javafx.scene.shape.Circle;
public final class ClientView {
 private final GridPane root=new GridPane(); private final Label target=new Label(); private final Label status=new Label("Offline"); private final Circle light=new Circle(6,Color.CRIMSON); private final TextField username=new TextField(); private final Button connect=new Button("CONNECT"); private final TextArea chat=new TextArea(); private final TextField message=new TextField(); private final Button send=new Button("SEND"); private final Button leave=new Button("LEAVE");
 public ClientView(){root.setPadding(new Insets(18));root.setHgap(10);root.setVgap(10);ColumnConstraints c1=new ColumnConstraints();c1.setPercentWidth(75);ColumnConstraints c2=new ColumnConstraints();c2.setPercentWidth(25);root.getColumnConstraints().addAll(c1,c2);Label title=new Label("Group Chat");title.getStyleClass().add("title");username.setPromptText("Username (blank = read-only)");chat.setEditable(false);chat.setWrapText(true);message.setPromptText("Message, allUsers, bye, or end");root.add(title,0,0);root.add(target,1,0);root.add(username,0,1);root.add(connect,1,1);root.add(new HBox(8,status,light),0,2);root.add(chat,0,3,2,1);root.add(message,0,4);root.add(send,1,4);root.add(leave,1,5);GridPane.setVgrow(chat,Priority.ALWAYS);setConnected(false,false);}
 public Parent root(){return root;} public void setTarget(String h,int p){target.setText(h+":"+p);} public String username(){return username.getText();} public String message(){return message.getText();} public void clearMessage(){message.clear();} public void append(String s){chat.appendText(s+System.lineSeparator());} public void onConnect(Runnable r){connect.setOnAction(e->r.run());} public void onSend(Runnable r){send.setOnAction(e->r.run());message.setOnAction(e->r.run());} public void onLeave(Runnable r){leave.setOnAction(e->r.run());}
 public void setConnected(boolean online,boolean ro){status.setText(online?(ro?"Online - READ ONLY":"Online"):"Offline");light.setFill(online?Color.LIMEGREEN:Color.CRIMSON);connect.setDisable(online);username.setDisable(online);send.setDisable(!online||ro);message.setDisable(!online||ro);leave.setDisable(!online);}
}
